# -*- coding: utf-8 -*-
import sqlite3, os, json
p = os.path.join('分析产出', '持仓面板', 'holding.sqlite')
c = sqlite3.connect(p)
trades = list(c.execute('select acct,code,name,side,date,shares,price,fee from trade order by date,id'))
cfg = json.loads(dict(c.execute("select k,v from setting where k='cfg'").fetchall())['cfg'])
targets = {t['code']: t for t in cfg['targets']}
rules = cfg['rules']
print('rules:', rules)
print()

# current positions (all trades applied)
pos = {}
for acct,code,name,side,date,sh,px,fee in trades:
    d = pos.setdefault(code, {'sh':0,'cost':0.0,'name':name})
    if side=='buy':
        d['cost'] += sh*px+fee
        d['sh'] += sh
    else:
        # reduce shares, reduce cost proportionally
        if d['sh']>0:
            d['cost'] *= (d['sh']-sh)/d['sh']
        d['sh'] -= sh
print('Current positions:')
for code,d in pos.items():
    if d['sh']>0:
        t=targets.get(code,{})
        print('  %s %s sh=%d avgcost=%.3f ind=%s w=%s' % (code, d['name'], d['sh'], d['cost']/d['sh'], t.get('ind'), t.get('w')))
print()

# Use live prices from screenshot: 格力 39.12, 永兴 15.13
live = {'000651':39.12, '601033':15.13}
# For others use ref_px
mv={}
for code,d in pos.items():
    if d['sh']>0:
        px = live.get(code) or targets.get(code,{}).get('ref_px') or 0
        mv[code]=d['sh']*px
Tmv=sum(mv.values())
print('Total MV=%.2f' % Tmv)
print('Per-code pct and industry aggregation:')
ind_mv={}
for code,v in mv.items():
    t=targets.get(code,{})
    pct=v/Tmv*100
    ind=t.get('ind')
    ind_mv[ind]=ind_mv.get(ind,0)+v
    print('  %s %s mv=%.0f pct=%.2f%% ind=%s' % (code, targets.get(code,{}).get('name'), v, pct, ind))
print('Industry pct (mv/Tmv):')
for k,v in ind_mv.items():
    print('  %s %.2f%%' % (k, v/Tmv*100))

