# -*- coding: utf-8 -*-
import sqlite3, os, json, math
p = os.path.join('分析产出', '持仓面板', 'holding.sqlite')
c = sqlite3.connect(p)
trades = list(c.execute('select acct,code,name,side,date,shares,price,fee from trade order by date,id'))
cfg = json.loads(dict(c.execute("select k,v from setting where k='cfg'").fetchall())['cfg'])
targets = {t['code']: t for t in cfg['targets']}
R = cfg['rules']

pos = {}
for acct,code,name,side,date,sh,px,fee in trades:
    d = pos.setdefault(code, {'sh':0,'cost':0.0,'name':name})
    if side=='buy':
        d['cost'] += sh*px+fee; d['sh'] += sh
    else:
        if d['sh']>0: d['cost'] *= (d['sh']-sh)/d['sh']
        d['sh'] -= sh

# live prices from screenshot
live = {'000651':39.12, '601033':15.13}
rows=[]
for code,d in pos.items():
    if d['sh']<=0: continue
    t=targets.get(code,{})
    px = live.get(code) or t.get('ref_px') or 0
    mv=d['sh']*px
    rows.append(dict(code=code,name=t.get('name'),ind=t.get('ind'),mkt=t.get('mkt'),w=t.get('w',0),sh=d['sh'],px=px,mv=mv))
Tmv=sum(r['mv'] for r in rows)

print('=== 风险预警口径 (base = T.mv = %.0f) ===' % Tmv)
for r in rows:
    pct=r['mv']/Tmv*100
    print('  %s 占比 %.2f%% (目标w=%.2f%%)' % (r['name'],pct,r['w']))
ind={}
for r in rows: ind[r['ind']]=ind.get(r['ind'],0)+r['mv']
for k,v in ind.items():
    print('  行业 %s = %.2f%%  (上限 %s%%)' % (k,v/Tmv*100,R['max_ind']))
devs=sorted([(r,r['mv']/Tmv*100-r['w']) for r in rows if r['w']>0], key=lambda x:-abs(x[1]))
print('  --- 权重偏离 top3 ---')
for r,dev in devs[:3]:
    if abs(dev)>=R['dev_warn']:
        targetMv=r['w']/100*Tmv; delta=r['mv']-targetMv
        if delta>0:
            sh=math.floor(delta/r['px']/100)*100
            act='需卖出约 %d 股(约 %.0f 元)'%(sh,sh*r['px'])
        else: act='需补约 %.0f 元'%(-delta)
        print('  %s %s %.2fpct, %s' % (r['name'],'超配' if dev>0 else '低配',abs(dev),act))

print()
print('=== 买入推荐口径 (base = max(total_capital=%s, mv+amount)) ===' % R['total_capital'])
amount=20000
base=max(R['total_capital'], Tmv+amount)
print('  base = %.0f' % base)
indUsed={}; mktUsed={'沪':0,'深':0}
for r in rows:
    indUsed[r['ind']]=indUsed.get(r['ind'],0)+r['mv']; mktUsed[r['mkt']]+=r['mv']
for r in rows:
    cap=min(r['w'], R['max_single'])
    capRoom=cap/100*base - r['mv']
    indRoom=R['max_ind']/100*base - indUsed[r['ind']]
    print('  %s: capPct=%.2f%% 上限市值=%.0f 当前mv=%.0f  单只余量=%.0f  行业余量=%.0f' % (
        r['name'], cap, cap/100*base, r['mv'], capRoom, indRoom))
    if r['mv'] >= cap/100*base - 1:
        print('      -> 买入侧: 已超/到上限，不买')
    elif indRoom <= 0:
        print('      -> 买入侧: 行业已满，不买')
    else:
        print('      -> 买入侧: 仍有额度，可买')

