  max_buys: 2,      // 本次最多买几只（控制 5 元最低佣金摩擦）
  min_ticket: 8000, // 单只最低买入额（元），低于则宁可减标的
  recent_trade_days: 3  // 近期交易互斥窗口（自然日）：窗口内刚买的不同向催卖、刚卖的不同向催买
};

/* ============================== 统一占比口径 ============================== */
/* 关键修复：预警与买入推荐必须用同一分母，否则会出现「同一只既提示超配卖出、又被推荐买入」。
   口径 = 总本金 total_capital（未建满仓时用已投入市值兜底取大者）。
   买入侧 buildPlan 早已用 base = max(total_capital, T.mv+amount)；这里把预警侧对齐到同口径。 */
function capitalBase(T) {
  const tc = +RULES.total_capital || 0;
  const mv = (T && T.mv) || 0;
  return tc > 0 ? Math.max(tc, mv) : mv;
}

/* 近期交易互斥护栏：返回 { code: {side, date, days} }，取每只「最近一笔」交易。
   - 窗口内刚买入(code最近为 buy)：预警不催卖、买入不重复建仓；
   - 窗口内刚卖出(code最近为 sell)：预警不催补、买入不催买回（避免刚卖又让买回）。 */
function recentTradeMap() {
  const win = +RULES.recent_trade_days;
  const days = win > 0 ? win : 0;
  const map = {};
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const list = (S.trades || []).slice().sort((a, b) =>
    (a.date < b.date ? -1 : a.date > b.date ? 1 : (a.id - b.id)));
  list.forEach(t => {
    const d = Date.parse(String(t.date)); if (!isFinite(d)) return;
    const diff = Math.round((today - new Date(d)) / 864e5);
    if (diff < 0 || diff > days) { if (!(t.code in map)) return; }
    map[t.code] = { side: t.side, date: t.date, days: diff };
  });
  // 只保留「最近一笔确在窗口内」的
  Object.keys(map).forEach(k => { if (map[k].days > days) delete map[k]; });
  return map;
}

/* ============================== 渲染 ============================== */
function render() {

// 统一占比分母：与买入推荐同口径（总本金 total_capital），避免「卖了又买/买了又说超配」
const CB = capitalBase(T);
const recent = recentTradeMap();
rows.forEach(r => {
  if (r.shares <= 0 || r.mv <= 0 || CB <= 0) return;
  const p = r.mv / CB * 100;
  if (p > (+RULES.max_single || 25))
    out.push(['bad', '×', esc(r.name) + ' 占比 ' + fmt(p, 2) + '%，超过单只上限 ' + (RULES.max_single || 25) + '%。']);
});
const byInd = {};
rows.forEach(r => { if (r.mv > 0) byInd[r.ind] = (byInd[r.ind] || 0) + r.mv; });
Object.keys(byInd).forEach(k => {
  const p = CB > 0 ? byInd[k] / CB * 100 : 0;
  if (p > (+RULES.max_ind || 35)) out.push(['bad', '×', esc(k) + ' 行业合计 ' + fmt(p, 2) + '%，超过 ' + (RULES.max_ind || 35) + '% 上限。']);
});

const devs = rows.filter(r => r.w > 0 && r.mv > 0).map(r => ({ row: r, name: r.name, dev: r.mv / CB * 100 - r.w }))
  .sort((a, b) => Math.abs(b.dev) - Math.abs(a.dev));
devs.slice(0, 3).forEach(d => {
  if (Math.abs(d.dev) >= (+RULES.dev_warn || 3)) {
    // #5 量化动作：超配→需卖出约 X 股(约 Y 元)；低配→需补约 Z 元
    const r = d.row, lot = +RULES.lot || 100;
    const rt = recent[r.code];
    // 互斥护栏：窗口内刚买入的不催卖；刚卖出的不催补（防止「刚买又说超配卖掉 / 刚卖又催买回」）
    if (d.dev < 0 && rt && rt.side === 'sell') {
      out.push(['ok', 'i', esc(d.name) + ' 低配 ' + fmt(Math.abs(d.dev), 2) + 'pct，但近 ' + rt.days + ' 日刚卖出，暂不催补（避免来回打脸）。']);
      return;
    }
    if (d.dev > 0 && rt && rt.side === 'buy') {
      out.push(['ok', 'i', esc(d.name) + ' 超配 ' + fmt(Math.abs(d.dev), 2) + 'pct，但近 ' + rt.days + ' 日刚买入，暂不催卖（避免来回打脸）。']);
      return;
    }
    const targetMv = r.w / 100 * CB;
    const deltaMv = r.mv - targetMv; // 正=超配需卖，负=低配需买
    let action;
    if (deltaMv > 0 && r.price > 0) {
      let sh = Math.floor(deltaMv / r.price / lot) * lot;
      action = '需卖出约 ' + fmt(sh, 0) + ' 股（约 ' + fmt(sh * r.price, 0) + ' 元）';
    } else if (deltaMv < 0) {
      action = '需补约 ' + fmt(-deltaMv, 0) + ' 元';
    } else { action = '下次投入优先调整'; }
    out.push(['warn', '!', esc(d.name) + (d.dev > 0 ? ' 超配 ' : ' 低配 ') + fmt(Math.abs(d.dev), 2) + 'pct，' + action + '。']);
  }
});

