/* ---------- 口径统一 + 近期交易互斥护栏 ---------- */
console.log('\n--- 预警/买入同口径 & 买卖互斥护栏 ---');
{
  const dS = new SQL.Database();
  dS.exec(SCHEMA); P._setDb(dS); P._seedInto(dS); P._readState();
  S.active = 'ALL';
  // 造持仓：洪城环境 mv 偏大；兴蓉环境刚买入；青岛港刚卖出
  dS.run('DELETE FROM trade');
  const ins = (code, name, side, date, sh, px) =>
    dS.run('INSERT INTO trade(acct,code,name,side,date,shares,price,fee,note) VALUES(?,?,?,?,?,?,?,?,?)',
      ['main', code, name, side, date, sh, px, 5, '']);
  const today = new Date(); const iso = dd => { const x=new Date(today); x.setDate(x.getDate()-dd);
    return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0'); };
  // 洪城环境：1200 股 @8.7（今日无交易，正常持仓）
  ins('600461', '洪城环境', 'buy', iso(300), 1200, 8.7);
  // 兴蓉环境：刚买入 600 股（窗口内 buy）→ 不应被催卖
  ins('000598', '兴蓉环境', 'buy', iso(200), 600, 7.3);
  ins('000598', '兴蓉环境', 'buy', iso(1), 600, 7.33);
  // 青岛港：刚卖出（窗口内 sell）→ 买入推荐不应催买回
  ins('601298', '青岛港', 'buy', iso(300), 1000, 9.7);
  ins('601298', '青岛港', 'sell', iso(1), 1000, 9.8);
  P._readState();
  P.applyConfig({ targets: sandbox.window.PANEL_CONFIG.targets,
    rules: Object.assign({}, sandbox.window.PANEL_CONFIG.rules, { total_capital: 100000, recent_trade_days: 3 }),
    margin: sandbox.window.PANEL_CONFIG.margin,
    margin_by_ind: sandbox.window.PANEL_CONFIG.margin_by_ind });
  // 给三只注入达标指标（marginBuy=true），让青岛港成为「本可买」的候选，以验证护栏拦住它
  P._clearMargin();
  const mk = (code, name, px) => ({ code: code, name: name, price: px, dps: 0.5, targetYld: 5.0,
    curYld: 6, yldAvg: 5, yldPct: 50, targetBuyAbsolute: px * 1.1, targetBuyConservative: px,
    boll: [{ n: 60, mid: px, sd: 0.01, lower: px, belowLower: false }] });
  P._setMargin('600461.SH', mk('600461', '洪城环境', 8.7));
  P._setMargin('000598.SZ', mk('000598', '兴蓉环境', 7.3));
  P._setMargin('601298.SH', mk('601298', '青岛港', 9.8));
  S.px = {
    '600461': { price: 8.7, prev: 8.7, chg: 0, name: '洪城环境', at: Date.now() },
    '000598': { price: 7.3, prev: 7.3, chg: 0, name: '兴蓉环境', at: Date.now() },
    '601298': { price: 9.8, prev: 9.8, chg: 0, name: '青岛港', at: Date.now() },
  };
  const rows = P.rowsNow(); const T = P.totals(rows);
  // 口径：capitalBase 必须是 total_capital（100000），而当前 T.mv 只有 ~2.6 万
  ok(P.capitalBase(T) === 100000, '口径统一: capitalBase = total_capital(100000)，实际 ' + P.capitalBase(T));
  ok(T.mv < 40000, '场景前提: 已投入市值(' + T.mv.toFixed(0) + ') 远小于总本金');
  // recentTradeMap：兴蓉最近为 buy、青岛港最近为 sell
  const rt = P.recentTradeMap();
  ok(rt['000598'] && rt['000598'].side === 'buy', '护栏: 兴蓉环境最近一笔识别为 buy');
  ok(rt['601298'] && rt['601298'].side === 'sell', '护栏: 青岛港最近一笔识别为 sell');
  ok(!rt['600461'], '护栏: 洪城环境窗口内无交易→不在 map');
  // 预警：按 total_capital 口径，洪城 8.7*1200=10440 → 10.44%，不应被判超配卖出；兴蓉刚买不催卖
  P.renderAlerts(rows, T);
  const alertHtml = String(el('alertBox').innerHTML || '');
  ok(!/洪城环境\s*超配/.test(alertHtml), '预警口径: 洪城环境(占10%)不再误报「超配需卖出」');
  ok(!/兴蓉环境[^。]*需卖出/.test(alertHtml), '护栏: 兴蓉环境刚买入→不催卖');
  ok(!/兴蓉环境\s*超配\s*[0-9.]*pct，需卖出/.test(alertHtml), '护栏: 兴蓉环境不含「超配…需卖出」指令');
  // 买入推荐：青岛港刚卖出→不应出现在买入清单
  const plan = P.buildPlan(20000, rows, T);
  const bought = plan.items.map(x => x.r.code);
  ok(!bought.includes('601298'), '护栏: 青岛港近3日刚卖出→本次不买回');
  ok(plan.skipped.some(x => x.r.code === '601298' && /刚卖出/.test(x.why)), '护栏: 青岛港进 skipped 且理由含「刚卖出」');
  P._clearMargin();
  P._setDb(dbOld); P._readState();
}

