tool_input.command:
$cfg = @"
# 持仓面板（数据湖）本地 nginx 部署 — 静态单页，root 指向面板目录
# 打开后按「选择数据库」加载 holding.sqlite 即可（浏览器 File System Access API）
server {
    listen 18093;
    server_name localhost;
    root D:/repository/数据湖/分析产出/持仓面板;
    index index.html;
    charset utf-8;

    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|wasm)$ {
        expires 1h;
        access_log off;
        try_files `$uri =404;
    }
    location / {
        try_files `$uri `$uri/ /index.html;
    }
}
"@
[System.IO.File]::WriteAllText('D:\nginx\conf\sites-enabled\持仓面板.conf', $cfg, (New-Object System.Text.UTF8Encoding($false)))
$ng='D:\nginx\nginx.exe'
& $ng -p 'D:\nginx\' -c 'conf/nginx.conf' -t 2>&1 | Out-Null
& $ng -p 'D:\nginx\' -c 'conf/nginx.conf' -s reload 2>&1 | Out-Null
Start-Sleep -Milliseconds 900
$r=Invoke-WebRequest -Uri 'http://127.0.0.1:18093/index.html' -UseBasicParsing -TimeoutSec 8
"HTTP $($r.StatusCode) len=$($r.Content.Length)"
foreach($m in @('function capitalBase','function recentTradeMap','recent_trade_days')){ if($r.Content.Contains($m)){"OK $m"}else{"MISS $m"} }
